using Dapper;
using MdwConteudos.Api.Infrastructure;

namespace MdwConteudos.Api.Modules.Orcamentos;

public static class OrcamentoSchema
{
    public static async Task MigrateAsync(IFirebirdConnectionFactory db, CancellationToken ct = default)
    {
        await using var c = await db.OpenConnectionAsync(ct);
        if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATIONS WHERE RDB$RELATION_NAME IN ('CLIENTE_COMERCIAL','ORCAMENTO_POLITICA','ORCAMENTO_CONFIG','ORCAMENTO_PROPOSTA','ORCAMENTO_REVISAO','ORCAMENTO_ITEM','ORCAMENTO_EDITOR','ORCAMENTO_EVENTO','ORCAMENTO_ANEXO')", cancellationToken: ct)) > 0)
            throw new InvalidOperationException("Esquema inicial de orçamentos com nomes antigos. Aplique, após backup e com a API parada, docs/sql/scripts/normalize-orcamentos-names.sql antes do migrador. O script exige tabelas sem dados comerciais.");
        var definitions = new Dictionary<string, string>
        {
            ["CLIENTECOMERCIAL"] = "CODCLIENTE INTEGER NOT NULL, VERSAO BIGINT NOT NULL, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, CONSTRAINT PK_CLIENTECOMERCIAL PRIMARY KEY(CODCLIENTE), CONSTRAINT FK_CLIENTECOMERCIAL_CODCLIENTE FOREIGN KEY(CODCLIENTE) REFERENCES CLIENTES(CODCLIENTE)",
            ["ORCAMENTOPOLITICA"] = "CODORCAMENTOPOLITICA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, CODUSUARIO INTEGER NOT NULL, MOTIVO VARCHAR(1000) CHARACTER SET UTF8 NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, CONSTRAINT PK_ORCAMENTOPOLITICA PRIMARY KEY(CODORCAMENTOPOLITICA)",
            ["ORCAMENTOCONFIG"] = "CODORCAMENTOCONFIG INTEGER NOT NULL, VERSAO BIGINT NOT NULL, CONSTRAINT PK_ORCAMENTOCONFIG PRIMARY KEY(CODORCAMENTOCONFIG)",
            ["ORCAMENTOPROPOSTA"] = "CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, EMAIL BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, PDF BLOB SUB_TYPE BINARY NOT NULL, SHA256 VARCHAR(64) CHARACTER SET ASCII NOT NULL, VERSAOTEMPLATE VARCHAR(40) CHARACTER SET ASCII NOT NULL, CODUSUARIO INTEGER NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, CONSTRAINT PK_ORC_PROPOSTA PRIMARY KEY(CODORCAMENTO,REVISAO)",
            ["ORCAMENTO"] = "CODORCAMENTO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CODCLIENTE INTEGER NOT NULL, REVISAO INTEGER NOT NULL, STATUS VARCHAR(30) CHARACTER SET ASCII NOT NULL, ARQUIVADO SMALLINT DEFAULT 0 NOT NULL, VERSAO BIGINT NOT NULL, DTHRULTMODIFICACAO TIMESTAMP NOT NULL, CONSTRAINT PK_ORCAMENTO PRIMARY KEY(CODORCAMENTO), CONSTRAINT FK_ORCAMENTO_CODCLIENTE FOREIGN KEY(CODCLIENTE) REFERENCES CLIENTES(CODCLIENTE)",
            ["ORCAMENTOREVISAO"] = "CODORCAMENTO BIGINT NOT NULL, NUMERO INTEGER NOT NULL, STATUS VARCHAR(30) CHARACTER SET ASCII NOT NULL, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, CODUSUARIO INTEGER NOT NULL, NOMEAUTOR VARCHAR(255) CHARACTER SET UTF8 NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, CONSTRAINT PK_ORC_REV PRIMARY KEY(CODORCAMENTO,NUMERO), CONSTRAINT FK_ORCAMENTOREVISAO_CODORCAMENTO FOREIGN KEY(CODORCAMENTO) REFERENCES ORCAMENTO(CODORCAMENTO)",
            ["ORCAMENTOITEM"] = "CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, POSICAO INTEGER NOT NULL, CATEGORIA VARCHAR(30) CHARACTER SET ASCII NOT NULL, DOCUMENTO BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, VALORBRUTO NUMERIC(18,2), DESCONTO NUMERIC(18,2), VALORFINAL NUMERIC(18,2), CONSTRAINT PK_ORC_ITEM PRIMARY KEY(CODORCAMENTO,REVISAO,POSICAO), CONSTRAINT FK_ORC_ITEM_REV FOREIGN KEY(CODORCAMENTO,REVISAO) REFERENCES ORCAMENTOREVISAO(CODORCAMENTO,NUMERO)",
            ["ORCAMENTO_USUARIO"] = "CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, CODUSUARIO INTEGER NOT NULL, CONSTRAINT PK_ORC_EDITOR PRIMARY KEY(CODORCAMENTO,REVISAO,CODUSUARIO), CONSTRAINT FK_ORC_EDITOR_REV FOREIGN KEY(CODORCAMENTO,REVISAO) REFERENCES ORCAMENTOREVISAO(CODORCAMENTO,NUMERO)",
            ["ORCAMENTOEVENTO"] = "CODORCAMENTOEVENTO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, ACAO VARCHAR(40) CHARACTER SET ASCII NOT NULL, STATUSANTERIOR VARCHAR(30) CHARACTER SET ASCII NOT NULL, STATUSPOSTERIOR VARCHAR(30) CHARACTER SET ASCII NOT NULL, CODUSUARIO INTEGER NOT NULL, NOMEAUTOR VARCHAR(255) CHARACTER SET UTF8 NOT NULL, MOTIVO VARCHAR(2000) CHARACTER SET UTF8 NOT NULL, REFERENCIA VARCHAR(500) CHARACTER SET UTF8 NOT NULL, DESTINO VARCHAR(500) CHARACTER SET UTF8 NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, CONSTRAINT PK_ORCAMENTOEVENTO PRIMARY KEY(CODORCAMENTOEVENTO), CONSTRAINT FK_ORCAMENTOEVENTO_CODORCAMENTO FOREIGN KEY(CODORCAMENTO) REFERENCES ORCAMENTO(CODORCAMENTO)",
            ["ORCAMENTOANEXO"] = "CODORCAMENTOANEXO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, NOME VARCHAR(255) CHARACTER SET UTF8 NOT NULL, MIME VARCHAR(120) CHARACTER SET ASCII NOT NULL, TAMANHO BIGINT NOT NULL, SHA256 VARCHAR(64) CHARACTER SET ASCII NOT NULL, TIPO VARCHAR(20) CHARACTER SET ASCII NOT NULL, CONTEUDO BLOB SUB_TYPE BINARY NOT NULL, CODUSUARIO INTEGER NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, CONSTRAINT FK_ORC_ANEXO_REV FOREIGN KEY(CODORCAMENTO,REVISAO) REFERENCES ORCAMENTOREVISAO(CODORCAMENTO,NUMERO), CONSTRAINT PK_ORCAMENTOANEXO PRIMARY KEY(CODORCAMENTOANEXO)"
        };
        foreach (var d in definitions)
            if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATIONS WHERE RDB$RELATION_NAME=@name", new { name = d.Key }, cancellationToken: ct)) == 0)
                await c.ExecuteAsync(new CommandDefinition($"CREATE TABLE {d.Key} ({d.Value})", cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM RDB$RELATION_CONSTRAINTS WHERE RDB$CONSTRAINT_NAME='FK_ORC_PROP_REV'") == 0)
            await c.ExecuteAsync(new CommandDefinition("ALTER TABLE ORCAMENTOPROPOSTA ADD CONSTRAINT FK_ORC_PROP_REV FOREIGN KEY(CODORCAMENTO,REVISAO) REFERENCES ORCAMENTOREVISAO(CODORCAMENTO,NUMERO)", cancellationToken: ct));
        foreach (var (name, target) in new[] { ("IX_ORC_DATA", "ORCAMENTO(DTHRULTMODIFICACAO,CODORCAMENTO)"), ("IX_ORC_CLIENTE", "ORCAMENTO(CODCLIENTE)"), ("IX_ORC_EVENTO", "ORCAMENTOEVENTO(CODORCAMENTO,CODORCAMENTOEVENTO)"), ("IX_ORC_ANEXO", "ORCAMENTOANEXO(CODORCAMENTO,REVISAO)") })
            if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM RDB$INDICES WHERE RDB$INDEX_NAME=@name", new { name }) == 0)
                await c.ExecuteAsync(new CommandDefinition($"CREATE INDEX {name} ON {target}", cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM ORCAMENTOPOLITICA") == 0)
            await c.ExecuteAsync(new CommandDefinition("INSERT INTO ORCAMENTOPOLITICA(DOCUMENTO,CODUSUARIO,MOTIVO,DTHRCRIACAO) VALUES(@json,0,'Referências iniciais do POP-GO-001 v1.0; nenhuma condição comercial presumida',@now)", new { json = QuoteTextBlob.Json(QuotePolicy.Initial), now = DateTime.UtcNow }, cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM ORCAMENTOCONFIG WHERE CODORCAMENTOCONFIG=1") == 0)
            await c.ExecuteAsync("INSERT INTO ORCAMENTOCONFIG(CODORCAMENTOCONFIG,VERSAO) SELECT 1,MAX(CODORCAMENTOPOLITICA) FROM ORCAMENTOPOLITICA");
        await OrcamentoAiSchema.Migrate(db, ct);
        await OrcamentoTechnicalSchema.Migrate(db, ct);
        await OrcamentoEmailSourceSchema.Migrate(db, ct);
        await ValidateAsync(db, ct);
    }

    public static async Task ValidateAsync(IFirebirdConnectionFactory db, CancellationToken ct = default)
    {
        await using var c = await db.OpenConnectionAsync(ct);
        await OrcamentoEmailSourceSchema.Validate(c, ct);
        foreach (var table in new[] { "CLIENTECOMERCIAL", "ORCAMENTOPOLITICA", "ORCAMENTOCONFIG", "ORCAMENTO", "ORCAMENTOREVISAO", "ORCAMENTOITEM", "ORCAMENTO_USUARIO", "ORCAMENTOEVENTO", "ORCAMENTOANEXO", "ORCAMENTOPROPOSTA", "ORCAMENTOANALISE", "ORCAMENTOREGRAVERSAO", "ORCAMENTOREGRACONFIG" })
            if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATIONS WHERE RDB$RELATION_NAME=@table", new { table }, cancellationToken: ct)) != 1)
                throw new InvalidOperationException("Schema de orçamentos ausente. Execute --migrate-database antes de iniciar a API.");
        if (await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM RDB$RELATION_FIELDS WHERE RDB$RELATION_NAME='ORCAMENTOANALISE' AND RDB$FIELD_NAME IN ('ETAPA','CODANALISEORIGEM','CONTEXTO')", cancellationToken: ct)) != 3
            || await c.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(*) FROM ORCAMENTOREGRACONFIG WHERE CODORCAMENTOREGRACONFIG=1", cancellationToken: ct)) != 1)
            throw new InvalidOperationException("Evolução de orçamentos incompleta. Execute --migrate-database para preparar fases, catálogo e permissões antes de iniciar a API.");
    }
}
